358	int PhysicsRayCast::fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
359	                               float maxDistance, RayCastHit* outHits, int maxHits)
360	{
361	    if (outHits == nullptr || maxHits <= 0 || numRays <= 0 || !_initialized)
362	    {
363	        return 0;
364	    }
365	
366	    Vec2 centreDirection;
367	    float length = 0.0f;
368	    if (!prepareRay(direction, maxDistance, _maxDistance, &centreDirection, &length))
369	    {
370	        return 0;
371	    }
372	
373	    cpSpace* space = activeSpace(_world, _space);
374	    if (space == nullptr)
375	    {
376	        return 0;
377	    }
378	
379	    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
380	
381	    // The sweep is symmetric around the centre direction: a single ray fires straight ahead,
382	    // otherwise the rays run from -angle/2 to +angle/2 in equal steps.
383	    float centreAngle = centreDirection.getAngle();
384	    float step = (numRays > 1) ? angle / static_cast<float>(numRays - 1) : 0.0f;
385	    float firstAngle = (numRays > 1) ? centreAngle - angle * 0.5f : centreAngle;
386	
387	    int found = 0;
388	    for (int i = 0; i < numRays && found < maxHits; ++i)
389	    {
390	        Vec2 rayDirection = Vec2::forAngle(firstAngle + step * static_cast<float>(i));
391	
392	        RayCastHit hit = {};
393	        if (segmentFirstHit(space, origin, rayDirection, length, filter, &hit))
394	        {
395	            outHits[found] = hit;
396	            ++found;
397	        }
398	    }
399	
400	    return found;
401	}
