519	float PhysicsRayCast::computeReflectionAngle(const Vec2& inDirection, const Vec2& normal)
520	{
521	    Vec2 reflected = computeReflectionDirection(inDirection, normal);
522	    if (reflected.lengthSquared() <= RAYCAST_DIRECTION_EPSILON_SQ)
523	    {
524	        return 0.0f;
525	    }
526	
