529	
530	Vec2 PhysicsRayCast::computeReflectionDirection(const Vec2& inDirection, const Vec2& normal)
531	{
532	    float normalLengthSq = normal.lengthSquared();
533	    if (normalLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
534	    {
535	        // Without a surface normal there is nothing to mirror against.
536	        return inDirection;
537	    }
538	
539	    Vec2 unitNormal = normal * (1.0f / std::sqrt(normalLengthSq));
540	
541	    // Mirror law r = d - 2 * (d . n) * n, which keeps the length of the incoming direction.
542	    return inDirection - unitNormal * (2.0f * inDirection.dot(unitNormal));
543	}
544	
545	Vec2 PhysicsRayCast::computeRefractionDirection(const Vec2& inDirection, const Vec2& normal, float ratio)
546	{
547	    float directionLengthSq = inDirection.lengthSquared();
548	    if (directionLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
549	    {
550	        return Vec2::ZERO;
551	    }
552	
553	    Vec2 incident = inDirection * (1.0f / std::sqrt(directionLengthSq));
554	
555	    float normalLengthSq = normal.lengthSquared();
556	    if (normalLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ || ratio <= 0.0f)
557	    {
558	        // No surface or no usable index ratio: the ray keeps travelling unbent.
559	        return incident;
560	    }
561	
562	    Vec2 unitNormal = normal * (1.0f / std::sqrt(normalLengthSq));
563	
564	    float cosIncident = incident.dot(unitNormal);
565	    if (cosIncident > 0.0f)
566	    {
567	        // The normal points along the ray, so flip it to face the incoming side.
568	        unitNormal = -unitNormal;
569	        cosIncident = -cosIncident;
570	    }
571	
572	    // Snell's law in vector form with ratio = n1 / n2.
573	    float k = 1.0f - ratio * ratio * (1.0f - cosIncident * cosIncident);
574	    if (k < 0.0f)
575	    {
576	        // Total internal reflection: the ray bounces off instead of crossing the surface.
577	        return computeReflectionDirection(incident, unitNormal);
578	    }
579	
580	    return incident * ratio - unitNormal * (ratio * cosIncident + std::sqrt(k));
581	}
